// The picture bench's cut of one owner photo for one frame (#340): written at the exact aspect of the demo file the
// site holds, at least the display box, around the subject and every face, enlarged at most 1.5 times and only through
// the sharpness gate. Every photo here is generated by code (_generated-photos.mjs): no real photo.
import assert from 'node:assert/strict'
import { test } from 'node:test'
import sharp from 'sharp'
import { cutPhoto, outputSizeFor } from '../src/site-pictures/cut-photo.js'
import { kinds, scene } from './_generated-photos.mjs'

const labels = (extra = {}) => ({
  subjectBox: [0.3, 0.2, 0.4, 0.6],
  faceBoxes: [],
  quality: 'high',
  ...extra
})

test('the output has the demo file aspect and covers the display box', () => {
  for (const [demo, box, natural] of [
    [{ width: 1920, height: 960 }, { width: 1440, height: 960 }, 3000],
    [{ width: 300, height: 300 }, { width: 200, height: 200 }, 250],
    [{ width: 1000, height: 300 }, { width: 700, height: 220 }, 500],
    [null, { width: 400, height: 250 }, 900]
  ]) {
    const out = outputSizeFor(demo, box, natural)
    const want = (demo ?? box).width / (demo ?? box).height
    assert.ok(Math.abs(out.width / out.height - want) <= 0.02, JSON.stringify({ demo, out }))
    assert.ok(out.width >= box.width && out.height >= box.height, JSON.stringify({ box, out }))
    assert.ok(
      out.width <= Math.max(natural, box.width, Math.ceil(box.height * want)) || out.width <= demo?.width
    )
  }
})

test('a large photo is cut around its subject, shrunk, at the demo file aspect, with no gate needed', async () => {
  const bytes = await scene('bakery', 1600, 1000)
  const got = await cutPhoto(bytes, labels(), { width: 600, height: 300 }, { width: 800, height: 400 })
  assert.equal(got.ok, true, JSON.stringify(got))
  assert.deepEqual([got.width, got.height], [800, 400])
  assert.ok(got.enlarge <= 1)
  assert.equal(got.sharpness, null)
  const meta = await sharp(got.bytes).metadata()
  assert.deepEqual([meta.width, meta.height], [800, 400])
  // The crop keeps the subject box (x 0.3 to 0.7 of 1600 px) whole.
  assert.ok(got.crop.x <= 480 && got.crop.x + got.crop.width >= 1120, JSON.stringify(got.crop))
  assert.equal(got.crop.width / got.crop.height, 2)
})

test('a face is never cut: a crop that cannot hold the face whole refuses the photo', async () => {
  const bytes = await scene('dental', 1600, 1000)
  const face = labels({ subjectBox: [0, 0.1, 1, 0.8], faceBoxes: [[0.02, 0.1, 0.96, 0.3]] })
  const got = await cutPhoto(bytes, face, { width: 300, height: 300 }, { width: 300, height: 300 })
  assert.deepEqual(got, { ok: false, refused: 'cuts-a-face' })
})

test('a crisp crop enlarged under 1.5 times into a small frame passes the gate; the gate is recorded', async () => {
  const bytes = await scene('dental', 260, 260)
  const got = await cutPhoto(bytes, labels(), { width: 360, height: 360 }, { width: 360, height: 360 })
  assert.equal(got.ok, true, JSON.stringify(got))
  assert.ok(got.enlarge > 1 && got.enlarge <= 1.5, String(got.enlarge))
  assert.equal(got.sharpness.passed, true)
  assert.equal(got.sharpness.bar, 'small')
  assert.deepEqual([got.width, got.height], [360, 360])
})

test('a soft crop that would be enlarged fails the gate and loses the frame', async () => {
  const { blurred } = await kinds('bakery', 260, 260)
  const got = await cutPhoto(blurred, labels(), { width: 360, height: 360 }, { width: 360, height: 360 })
  assert.equal(got.ok, false)
  assert.equal(got.refused, 'unsharp')
  assert.equal(got.sharpness.passed, false)
})

test('a photo that would need more than 1.5 times is refused before any gate', async () => {
  const bytes = await scene('bakery', 200, 200)
  const got = await cutPhoto(bytes, labels(), { width: 360, height: 360 }, { width: 360, height: 360 })
  assert.deepEqual(got, { ok: false, refused: 'too-small' })
})

test('a low quality photo goes through the gate even when not enlarged, and never into a large frame', async () => {
  const bytes = await scene('dental', 500, 500)
  const small = await cutPhoto(
    bytes,
    labels({ quality: 'low' }),
    { width: 200, height: 200 },
    { width: 300, height: 300 }
  )
  assert.equal(small.ok, true, JSON.stringify(small))
  assert.equal(small.sharpness.passed, true)
  const large = await cutPhoto(
    bytes,
    labels({ quality: 'low' }),
    { width: 700, height: 700 },
    { width: 700, height: 700 }
  )
  assert.deepEqual(large, { ok: false, refused: 'low-quality-in-a-large-frame' })
})
